        /// Issue #80: play what browse_items would list for these arguments ("Play these").
        fn queue_play_query(
            self: &Core,
            request_id: u64,
            kind: &str,
            sort: &str,
            filter: &str,
            start_item: i64,
            shuffle: bool,
        );
