fn detail(d: core::Detail) -> ffi::ItemDetail {
    let meta: serde_json::Value = serde_json::from_str(&d.meta_json).unwrap_or_default();
    ffi::ItemDetail {
        genres: strings(&meta, "genres"),
        cast: strings(&meta, "cast"),
        item: summary(d.item),
        original_title: d.original_title,
        rating: d.rating.unwrap_or(-1.0),
        runtime_min: d.runtime_min.unwrap_or(0) as i32,
        backdrop: d.backdrop,
        poster_full: d.poster_full,
        match_state: d.match_state,
        tmdb_id: d.tmdb_id.unwrap_or(0),
        parent_title: d.parent_title,
        files: d.files.into_iter().map(file_ref).collect(),
        position_ms: d.position_ms,
        duration_ms: d.duration_ms,
        last_file_id: d.last_file_id,
        children: d.children.into_iter().map(summary).collect(),
        next_up: d.next_up.into_iter().map(summary).collect(),
        save: save_info(d.save),
    }
}

fn convert(e: core::Event) -> ffi::CoreEvent {
    use ffi::EventKind as K;
    match e {
        core::Event::Folder {
            request_id,
            path,
            parent,
            entries,
        } => ffi::CoreEvent {
            path,
            parent,
            entries: entries
                .into_iter()
                .map(|e| ffi::FsEntry {
                    name: e.name,
                    path: e.path,
                    is_dir: e.is_dir,
                    is_video: e.is_video,
                    size: e.size,
                    progress: e.progress,
                    watched: e.watched,
                })
                .collect(),
            ..event(K::Folder, request_id)
        },
        core::Event::Playback {
            request_id,
            ticket: t,
        } => ffi::CoreEvent {
            item_id: t.item_id,
            ticket: ffi::Ticket {
                ticket: t.ticket,
                item_id: t.item_id,
                title: t.title,
                url: t.url,
                is_network: t.is_network,
                resume_ms: t.resume_ms,
                subtitles: t
                    .subtitles
                    .into_iter()
                    .map(|s| ffi::Subtitle {
                        url: s.url,
                        lang: s.lang,
                        forced: s.forced,
                    })
                    .collect(),
                audio_langs: t.audio_langs.join(","),
                sub_langs: t.sub_langs.join(","),
                sub_off: t.prefs.sub_off,
            },
            ..event(K::Playback, request_id)
        },
        core::Event::ContinueWatching { request_id, items } => ffi::CoreEvent {
            recent: items
                .into_iter()
                .map(|r| ffi::RecentItem {
                    item_id: r.item_id,
                    title: r.title,
                    path: r.path,
                    position_ms: r.position_ms,
                    duration_ms: r.duration_ms,
                })
                .collect(),
            ..event(K::ContinueWatching, request_id)
        },
        core::Event::ItemChanged { item_id } => ffi::CoreEvent {
            item_id,
            ..event(K::ItemChanged, 0)
        },
        core::Event::Error {
            request_id,
            kind,
            message,
        } => ffi::CoreEvent {
            error: match kind {
                core::ErrorKind::Auth => ffi::ErrorKind::Auth,
                core::ErrorKind::Unreachable => ffi::ErrorKind::Unreachable,
                core::ErrorKind::NotFound => ffi::ErrorKind::NotFound,
                core::ErrorKind::Unsupported => ffi::ErrorKind::Unsupported,
                core::ErrorKind::Internal => ffi::ErrorKind::Internal,
                core::ErrorKind::NoSpace => ffi::ErrorKind::NoSpace,
            },
            message,
            ..event(K::Error, request_id)
        },
        core::Event::Page {
            request_id,
            total,
            offset,
            items,
        } => ffi::CoreEvent {
            total,
            offset,
            items: items.into_iter().map(summary).collect(),
            ..event(K::Page, request_id)
        },
        core::Event::Episodes {
            request_id,
            total,
            offset,
            items,
        } => ffi::CoreEvent {
            total,
            offset,
            episodes: items.into_iter().map(episode).collect(),
            ..event(K::Episodes, request_id)
        },
        core::Event::Detail {
            request_id,
            detail: d,
        } => ffi::CoreEvent {
            item_id: d.item.id,
            detail: detail(*d),
            ..event(K::Detail, request_id)
        },
        core::Event::Libraries {
            request_id,
            libraries,
        } => ffi::CoreEvent {
            libraries: libraries
                .into_iter()
                .map(|l| ffi::LibraryFolder {
                    id: l.id,
                    kind: l.kind,
                    name: l.name,
                    root: l.root,
                    files: l.files,
                    last_scan_ms: l.last_scan_ms,
                    scanning: l.scanning,
                    online: l.online,
                    content: l.content,
                })
                .collect(),
            ..event(K::Libraries, request_id)
        },
        core::Event::Review { request_id, items } => ffi::CoreEvent {
            review: items
                .into_iter()
                .map(|r| ffi::ReviewEntry {
                    item: summary(r.item),
                    candidates: r.candidates.into_iter().map(candidate).collect(),
                })
                .collect(),
            ..event(K::Review, request_id)
        },
        core::Event::Candidates {
            request_id,
            item_id,
            candidates,
        } => ffi::CoreEvent {
            item_id,
            candidates: candidates.into_iter().map(candidate).collect(),
            ..event(K::Candidates, request_id)
        },
        core::Event::ScanState {
            source_id,
            running,
            message,
        } => ffi::CoreEvent {
            source_id,
            flag: running,
            message,
            ..event(K::ScanState, 0)
        },
        core::Event::LibraryChanged { queued, failed } => ffi::CoreEvent {
            queued,
            failed,
            ..event(K::LibraryChanged, 0)
        },
        core::Event::MusicDetail {
            request_id,
            kind,
            json,
        } => ffi::CoreEvent {
            path: kind,
            message: json,
            ..event(K::MusicDetail, request_id)
        },
        core::Event::QueueChanged { request_id, json } => ffi::CoreEvent {
            message: json,
            ..event(K::QueueChanged, request_id)
        },
        core::Event::MusicKeys { request_id, json } => ffi::CoreEvent {
            message: json,
            ..event(K::MusicKeys, request_id)
        },
        core::Event::MusicTickets { json } => ffi::CoreEvent {
            message: json,
            ..event(K::MusicTickets, 0)
        },
        core::Event::MusicOnline { request_id, online } => ffi::CoreEvent {
            flag: online,
            ..event(K::MusicOnline, request_id)
        },
        core::Event::KeyStatus {
            request_id,
            has_key,
            from_env,
            message,
            state,
            validated_at,
        } => ffi::CoreEvent {
            key_state: state,
            validated_at,
            flag: has_key,
            flag2: from_env,
            message,
            ..event(K::KeyStatus, request_id)
        },
        core::Event::Discovered {
            request_id,
            devices,
        } => ffi::CoreEvent {
            servers: devices
                .into_iter()
                .map(|d| ffi::DiscoveredServer {
                    name: d.name,
                    protocol: d.protocol,
                    host: d.host,
                    port: d.port,
                    tls: d.tls,
                })
                .collect(),
            ..event(K::Discovered, request_id)
        },
        core::Event::ExportConflict { request_id, paths } => ffi::CoreEvent {
            paths,
            ..event(K::ExportConflict, request_id)
        },
        core::Event::SaveState {
            request_id,
            item_id,
            info,
        } => ffi::CoreEvent {
            item_id,
            save: save_info(info),
            ..event(K::SaveState, request_id)
        },
        core::Event::Downloads {
            request_id,
            items,
            used_bytes,
            storage_dir,
        } => ffi::CoreEvent {
            downloads: items.into_iter().map(download_entry).collect(),
            used_bytes,
            path: storage_dir,
            ..event(K::Downloads, request_id)
        },
        core::Event::DownloadProgress {
            id,
            main_id,
            item_id,
            kind,
            state,
            bytes_done,
            size,
            error_kind,
            error,
        } => ffi::CoreEvent {
            item_id,
            download: ffi::DownloadEntry {
                id,
                main_id,
                item_id,
                kind,
                state,
                bytes_done,
                size,
                error_kind,
                error,
                ..Default::default()
            },
            ..event(K::DownloadProgress, 0)
        },
    }
}

/// Run `f`, turning a panic into a log line instead of unwinding into C++.
fn guard(what: &str, f: impl FnOnce()) {
    if catch_unwind(AssertUnwindSafe(f)).is_err() {
        eprintln!("coyotl core: panic in {what}");
    }
}

fn core_open(
    data_dir: &str,
    language: &str,
    sink: cxx::UniquePtr<ffi::EventSink>,
) -> Result<Box<Core>, String> {
    let sink = CxxSink(sink);
    catch_unwind(AssertUnwindSafe(|| {
        core::Core::open(
            std::path::Path::new(data_dir),
            language,
            move |e: core::Event| {
                sink.post(&convert(e));
            },
        )
        .map(|c| Box::new(Core(c)))
        .map_err(|e| e.to_string())
    }))
    .unwrap_or_else(|_| Err("internal error while opening the core".into()))
}

fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

fn log_message(level: u8, category: &str, message: &str) {
    guard("log_message", || {
        core::diagnostics::log_external(level, category, message)
    });
}

